// Package preset writes generated files under src/data/ deterministically:
// the same inputs give the same bytes, and the header records which fog
// command wrote the file and the SHA-256 of every input it read. No date
// and no fog version are written, so regenerating with unchanged inputs
// and unchanged code never produces a diff; a code change that alters the
// output is caught by `fog build --check`.
package preset

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

// File is one generated JS module.
type File struct {
	Out     string   // path relative to the repo root, e.g. src/data/presets/seis-krakatoa.js
	Command string   // fog sub-command that writes it, e.g. "build krakatoa"
	Inputs  []string // repo-relative input files, hashed into the header
	Notes   []string // free description lines (units, conventions), without "// "
	Body    string   // the module itself (export const …), ending with "\n"
	// NoHeader writes Body alone: a format without comments (CSV). Its
	// provenance is then that of the other files of the same target.
	NoHeader bool
}

// SHA256File returns the hex SHA-256 of a file.
func SHA256File(path string) (string, error) {
	f, err := os.Open(path)
	if err != nil {
		return "", err
	}
	defer f.Close()
	h := sha256.New()
	if _, err := io.Copy(h, f); err != nil {
		return "", err
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}

// Render returns the full file content.
func (f File) Render(root string) ([]byte, error) {
	if f.NoHeader { // written as is (json.dump writes no final newline)
		return []byte(f.Body), nil
	}
	if !strings.HasSuffix(f.Body, "\n") {
		return nil, fmt.Errorf("%s: body must end with a newline", f.Out)
	}
	var b bytes.Buffer
	fmt.Fprintf(&b, "// GENERATED by `fog %s` (tools/) -- do not edit by hand.\n", f.Command)
	for _, in := range f.Inputs {
		sum, err := SHA256File(filepath.Join(root, in))
		if err != nil {
			return nil, err
		}
		fmt.Fprintf(&b, "// input %s sha256:%s\n", in, sum)
	}
	for _, n := range f.Notes {
		if strings.Contains(n, "\n") {
			return nil, fmt.Errorf("%s: note line contains a newline", f.Out)
		}
		b.WriteString("// " + n + "\n")
	}
	b.WriteString(f.Body)
	return b.Bytes(), nil
}

// Status of a Write.
type Status int

const (
	Unchanged Status = iota // file already had these bytes
	Written                 // file created or replaced
	Stale                   // check mode: file differs, nothing written
)

func (s Status) String() string {
	return [...]string{"unchanged", "written", "STALE"}[s]
}

// Write renders f and writes it under root, or, with check, only compares.
// The write goes through a temporary file and a rename, so an interrupted
// run never leaves half a preset.
func Write(root string, f File, check bool) (Status, error) {
	data, err := f.Render(root)
	if err != nil {
		return 0, err
	}
	path := filepath.Join(root, f.Out)
	old, err := os.ReadFile(path)
	if err == nil && bytes.Equal(old, data) {
		return Unchanged, nil
	}
	if err != nil && !os.IsNotExist(err) {
		return 0, err
	}
	if check {
		return Stale, nil
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return 0, err
	}
	tmp, err := os.CreateTemp(filepath.Dir(path), ".fog-*")
	if err != nil {
		return 0, err
	}
	defer os.Remove(tmp.Name())
	if _, err := tmp.Write(data); err != nil {
		tmp.Close()
		return 0, err
	}
	if err := tmp.Close(); err != nil {
		return 0, err
	}
	if err := os.Chmod(tmp.Name(), 0o644); err != nil {
		return 0, err
	}
	if err := os.Rename(tmp.Name(), path); err != nil {
		return 0, err
	}
	return Written, nil
}
